/**
 * rules.test.ts — the TS mirror must agree with the Python engine on every
 * shared test vector (data/test-vectors.json, generated by the pipeline),
 * plus unit checks on the scoring rules.
 */
import { describe, expect, it } from "vitest";
import {
  chaseDraft,
  recommendedAction,
  recommendedPromiseDays,
  routeSeller,
  round1,
  scoreSeller,
} from "./rules";
import type { SellerRow } from "./types";
import vectorsJson from "../public/data/test-vectors.json";

describe("shared test vectors (Python/TS contract)", () => {
  it("has 12 vectors", () => {
    expect(vectorsJson.vectors).toHaveLength(12);
  });

  for (const v of vectorsJson.vectors) {
    it(`vector ${v.input.n} orders, ${v.input.late_orders} late -> score ${v.expected.score} ${v.expected.route}`, () => {
      const { score, parts } = scoreSeller(v.input);
      expect(score).toBe(v.expected.score);
      expect(parts).toEqual(v.expected.parts);
      expect(routeSeller(score, v.input.n)).toBe(v.expected.route);
    });
  }
});

describe("round1 matches Python round(x, 1)", () => {
  it("rounds half to even", () => {
    expect(round1(2.25)).toBe(2.2);
    expect(round1(2.35)).toBe(2.4);
    expect(round1(12.25)).toBe(12.2);
  });
  it("rounds ordinary values", () => {
    expect(round1(67.19999999999999)).toBe(67.2);
    expect(round1(0.05)).toBe(0.1);
  });
});

function seller(over: Partial<SellerRow> = {}): SellerRow {
  return {
    seller_id: "test-seller",
    seller_state: "SP",
    seller_city: "sao paulo",
    orders: 10,
    late_orders: 0,
    late_rate: 0,
    median_slip: -10,
    late_median_slip: 0,
    max_slip: -5,
    worst_order_id: "o1",
    breach_orders: 0,
    breach_rate: 0,
    sep_late_rate: 0,
    sep_n: 5,
    ja_late_rate: 0,
    ja_n: 5,
    promised_median_days: 22,
    p90_transit_days: 19,
    recommended_promise_days: 19,
    reset_lead_time: false,
    overdue_open: 0,
    score: 0,
    score_parts: { late_rate: 0, severity: 0, breach: 0, trend: 0, worst: 0 },
    route: "RELIABLE",
    action: "NO ACTION",
    instruction: "",
    draft: "",
    pending_approval: true,
    ...over,
  };
}

describe("scoring rules", () => {
  it("all on time scores 0 and is RELIABLE", () => {
    const { score } = scoreSeller({
      n: 10, late_orders: 0, late_rate: 0, late_median_slip: 0, max_slip: -5,
      breach_rate: 0, sep_late_rate: 0, sep_n: 5, ja_late_rate: 0, ja_n: 5,
    });
    expect(score).toBe(0);
    expect(routeSeller(score, 10)).toBe("RELIABLE");
  });

  it("half late escalates at 49", () => {
    const { score, parts } = scoreSeller({
      n: 10, late_orders: 5, late_rate: 0.5, late_median_slip: 10, max_slip: 12,
      breach_rate: 0.2, sep_late_rate: 0.6, sep_n: 5, ja_late_rate: 0.4, ja_n: 5,
    });
    expect(score).toBe(49);
    expect(parts.trend).toBe(10);
    expect(routeSeller(score, 10)).toBe("ESCALATE");
  });

  it("trend guard needs two orders each side", () => {
    const { score, parts } = scoreSeller({
      n: 6, late_orders: 2, late_rate: 0.333, late_median_slip: 5, max_slip: 8,
      breach_rate: 0, sep_late_rate: 1, sep_n: 1, ja_late_rate: 0, ja_n: 5,
    });
    expect(parts.trend).toBe(0);
    expect(score).toBe(20.5);
    expect(routeSeller(score, 6)).toBe("WATCH");
  });

  it("under five orders is UNSCORED", () => {
    expect(routeSeller(51.5, 3)).toBe("UNSCORED");
  });

  it("segment boundaries", () => {
    expect(routeSeller(45, 10)).toBe("ESCALATE");
    expect(routeSeller(44.9, 10)).toBe("AT_RISK");
    expect(routeSeller(30, 10)).toBe("AT_RISK");
    expect(routeSeller(29.9, 10)).toBe("WATCH");
    expect(routeSeller(12, 10)).toBe("WATCH");
    expect(routeSeller(11.9, 10)).toBe("RELIABLE");
  });

  it("lead-time reset needs a 5-day gap", () => {
    expect(recommendedPromiseDays(42.2, 26)).toEqual({ rec: 43, reset: true });
    expect(recommendedPromiseDays(24, 20)).toEqual({ rec: 24, reset: false });
  });

  it("reset beats chase in action priority", () => {
    const { action } = recommendedAction(
      seller({ route: "ESCALATE", reset_lead_time: true, recommended_promise_days: 43, p90_transit_days: 42.2, promised_median_days: 26, overdue_open: 5 }),
    );
    expect(action).toBe("RESET LEAD TIME");
  });

  it("draft names real numbers and is gated", () => {
    const s = seller({
      route: "ESCALATE", orders: 6, late_orders: 4, late_rate: 0.667,
      late_median_slip: 14.5, max_slip: 19, breach_rate: 0.833,
      reset_lead_time: true, recommended_promise_days: 43,
      p90_transit_days: 42.2, promised_median_days: 26, overdue_open: 1,
    });
    const draft = chaseDraft(s);
    expect(draft).toContain("66.7%");
    expect(draft).toContain("43 days");
    expect(draft).toContain("Nothing has been sent");
  });
});
